import Tabs from "@marko-ui/shadcn/ui/tabs/tabs.marko";

static const STATUS_TABS = [
  { value: "active", label: "Active" },
  { value: "pending", label: "Pending" },
  { value: "archived", label: "Archived", disabled: true },
];

<Tabs|value| items=STATUS_TABS class="w-[400px]">
  <p class="text-muted-foreground text-sm">Showing ${value} items.</p>
</Tabs>

import Tabs from "@marko-ui/shadcn/ui/tabs/tabs.marko";

<Tabs|value| items=[{ value: "one", label: "Items One" }, { value: "two", label: "Items Two" }]>
  <@trigger value="one">Tag One</@trigger>
  <@trigger value="two">Tag Two</@trigger>
  Panel for ${value}
</Tabs>
